CREATE TABLE IF NOT EXISTS gis_phase370_boundary_validation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, candidate_id TEXT NOT NULL, source_identity_pass BOOLEAN NOT NULL DEFAULT false, feature_inventory_pass BOOLEAN NOT NULL DEFAULT false, state_coverage_pass BOOLEAN NOT NULL DEFAULT false, geometry_evidence_pass BOOLEAN NOT NULL DEFAULT false, feature_relationship_pass BOOLEAN NOT NULL DEFAULT false, evidence_score DOUBLE PRECISION NOT NULL DEFAULT 0, lga_ward_assertions_enabled BOOLEAN NOT NULL DEFAULT false, validation_status TEXT NOT NULL, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(certification_version,candidate_id));